import React, { useContext } from 'react';
import { useIntl } from 'react-intl';

import {
  ChevronLeftSmallIcon,
  ChevronRightSmallIcon,
} from '@dynatrace/strato-icons';

import { Button } from '../../../buttons/button/Button.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { TablePaginationContext } from '../../contexts/TablePaginationContext.js';

type PrevNextButtonsProps = {
  updatePageIndex: (
    newPageIndex: number,
    trigger?: 'user' | 'internal',
    currentPageSize?: number | undefined,
  ) => void;
  enablePrevPage?: boolean;
  enableNextPage?: boolean;
};

export function PrevNextButtons(props: PrevNextButtonsProps) {
  const { pageIndex, manualPagination, canPreviousPage, canNextPage } =
    useContext(TablePaginationContext);

  const { updatePageIndex, enablePrevPage, enableNextPage } = props;

  const intl = useIntl();

  return (
    <Flex gap={2}>
      <Button
        onClick={() => updatePageIndex(pageIndex - 1)}
        disabled={manualPagination ? !enablePrevPage : !canPreviousPage}
        aria-label={intl.formatMessage({
          defaultMessage: 'Go to previous page.',
          id: 'VoqQWp9yEM0QM8eF',
          description: 'Aria label to add to the `previous` button',
        })}
        variant="default"
      >
        <Button.Prefix>
          <ChevronLeftSmallIcon />
        </Button.Prefix>
      </Button>
      <Button
        onClick={() => updatePageIndex(pageIndex + 1)}
        disabled={manualPagination ? !enableNextPage : !canNextPage}
        aria-label={intl.formatMessage({
          defaultMessage: 'Go to next page.',
          id: 'KAAzM9PVtiJno9ks',
          description: 'Aria label to add to the `next` button',
        })}
        variant="default"
      >
        <Button.Prefix>
          <ChevronRightSmallIcon />
        </Button.Prefix>
      </Button>
    </Flex>
  );
}
